const b = await show({ read: "window.overview", form: "bars", path: "workstreams", label: "name", value: "moved", caption: "Items moved since you last looked (1 Oct), by workstream" });
return { b, items: o.workstreams.map(w => ({ id: w.id, moved: w.movedItems })) };

